const ALL_PROFILE_TAGS = [...new Set(PROFILES.flatMap(p => p.tags))];
const tagCount = t => PROFILES.filter(p => p.tags.includes(t)).length;
const R = () => (typeof ROOT !== "undefined" ? ROOT : "");
